spec.command:
set -o pipefail
{
  for x in llvm-objdump llvm-readobj rizin rz-bin rz-asm radare2 r2 ghidraRun analyzeHeadless go; do printf '%s\t' "$x"; command -v "$x" || true; done
  echo '--- python modules ---'
  python3 - <<'PY'
mods=['distorm3','iced_x86','zydis','capstone','pefile']
for m in mods:
 try:
  x=__import__(m); print(m,'YES',getattr(x,'__version__',''))
 except Exception as e: print(m,'NO',repr(e))
PY
  echo '--- go tool objdump help ---'; go tool objdump -h 2>&1 || true
  echo '--- go tool nm help ---'; go tool nm -h 2>&1 || true
  for x in llvm-objdump llvm-readobj rizin radare2; do if command -v "$x" >/dev/null; then echo "--- $x help ---"; "$x" --help 2>&1 | head -80; fi; done
} > "$OUT/availability.txt"
cat "$OUT/availability.txt"
